public final class Sensor implements Listener {
    private final int[] calibration;

    public Sensor(EventBus bus) {
        bus.register(this);              // this thoat ra TRUOC khi freeze
        this.calibration = load();       // thread khac co the doc calibration == null
    }

    public void onEvent() { use(calibration); }
}

// DUNG: construct xong han roi moi dang ky
public final class Sensor implements Listener {
    private final int[] calibration;

    private Sensor() { this.calibration = load(); }

    public static Sensor newInstance(EventBus bus) {
        Sensor s = new Sensor();         // constructor da ket thuc -> freeze da xay ra
        bus.register(s);
        return s;
    }

    public void onEvent() { use(calibration); }
}

// Producer-consumer voi hang doi CO GIOI HAN + poison pill
final BlockingQueue<String> queue = new ArrayBlockingQueue<>(1000);
final String POISON = new String("POISON"); // so sanh bang ==

Runnable producer = () -> {
    try {
        for (String line : source) {
            queue.put(line);          // BI CHAN khi day -> backpressure
        }
        queue.put(POISON);
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }
};

Runnable consumer = () -> {
    try {
        while (true) {
            String item = queue.take();
            if (item == POISON) { queue.put(POISON); break; } // truyen tiep cho consumer khac
            handle(item);
        }
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }
};

