// clone() mac dinh la SHALLOW COPY
class Team implements Cloneable {
    String name;
    List<String> members = new ArrayList<>();

    @Override public Team clone() throws CloneNotSupportedException {
        return (Team) super.clone();     // members dung chung!
    }
}

Team a = new Team();
a.name = "A";
a.members.add("an");

Team b = a.clone();
b.name = "B";
b.members.add("binh");

System.out.println(a.name);           // A   (String immutable, gan lai khong anh huong)
System.out.println(a.members.size());  // 2  <-- ban goc bi sua!

