// PHIEN BAN THAY THE: bo hoan toan Cloneable, dung copy constructor
// ------------------------------------------------------------
class Team {
    final String name;
    final List<String> members;

    Team(String name, List<String> members) {
        this.name = name;
        this.members = new ArrayList<>(members);   // defensive copy
    }

    Team(Team other) {
        this(other.name, other.members);
    }
}

