public class CacheService {
    private final byte[] hugeBuffer = new byte[64 * 1024 * 1024];

    // RO RI: inner class giu this$0 -> giu luon hugeBuffer
    class Cleaner implements Runnable {
        @Override public void run() { /* khong dung gi cua outer */ }
    }

    // RO RI: lambda cham vao field instance -> capture this
    Runnable leaky() {
        return () -> System.out.println("size=" + hugeBuffer.length);
    }

    // SUA: static nested class, truyen tuong minh cai can dung
    static class SafeCleaner implements Runnable {
        private final int size;
        SafeCleaner(int size) { this.size = size; }
        @Override public void run() { System.out.println("size=" + size); }
    }

    // SUA: copy ra bien local truoc, lambda chi capture gia tri do
    Runnable safe() {
        int size = hugeBuffer.length;
        return () -> System.out.println("size=" + size);
    }
}

