public class Outer {
    String name = "Outer";

    Runnable anonymous() {
        return new Runnable() {
            public void run() { System.out.println(this.getClass().getName()); }
        };
    }

    Runnable lambda() {
        return () -> System.out.println(this.getClass().getName());
    }

    public static void main(String[] a) {
        Outer o = new Outer();
        o.anonymous().run();
        o.lambda().run();
    }
}

class Point {
    final int x, y;
    Point(int x, int y) { this.x = x; this.y = y; }

    @Override public boolean equals(Object o) {
        if (!(o instanceof Point)) return false;
        Point p = (Point) o;
        return p.x == x && p.y == y;
    }
    @Override public int hashCode() { return 31 * x + y; }
}

class ColorPoint extends Point {
    final String color;
    ColorPoint(int x, int y, String c) { super(x, y); color = c; }

    @Override public boolean equals(Object o) {
        if (!(o instanceof ColorPoint)) return false;
        return super.equals(o) && ((ColorPoint) o).color.equals(color);
    }
    @Override public int hashCode() { return super.hashCode() * 31 + color.hashCode(); }
}

Point p = new Point(1, 2);
ColorPoint cp = new ColorPoint(1, 2, "do");

System.out.println(p.equals(cp));
System.out.println(cp.equals(p));
System.out.println(Arrays.asList((Point) cp).contains(p));

